%     sat.area, sat.pos, sat.normal, sat.uu, sat.uv, sat.qlb, sat.Ca, sat.Cd, sat.Cs, sat.nu, sat.nv, sat.F0],'sat.csv');
% writematrix(["Jxx",'Jyy','Jzz', 'm';
%     sat.MOI(1,1), sat.MOI(2,2), sat.MOI(3,3), sat.m],'satMass.csv');


